def cdir(slug,country,cname):
    return mk(slug,f'Meta Appeal Links for {country} (2026): Instagram, Facebook, Ads',f'Meta appeal links {country}',
     f'Official Meta appeal links for Instagram, Facebook and ad accounts in {country}, with what each one is for. Checked November 2026.',
     f'Meta appeal links for {country}',f'The same official links work in {country} as everywhere else. This page lists them, with notes for people in {cname}.',
     f'<strong>In {country}, Instagram and Facebook appeals start from the notice you see when you log in, or from Account Status in the app.</strong> Ad accounts and Pages are reviewed in Business Support Home. Meta does not take appeals by email or phone. Use the device you normally use and appeal once. Meta makes the final decision.',
     [('Instagram','Notice at login, then Account Status.'),('Facebook','Notice at login, then Accounts Center.'),('Ads','Business Support Home on a computer.')],
     f'<h2 id="local-notes">Notes for {country}</h2><ul><li>Meta’s apps work in Arabic and English. If your appeal screen is in Arabic, you can write the appeal in Arabic or English.</li><li>Use your normal mobile network. Many people use a VPN for other apps; turn it off before you appeal.</li><li>If your ID is not in Latin script, upload it as it is. Do not edit or translate the image.</li></ul>',
     [('ig','Instagram',IG[:4]),('fb','Facebook',FB[:4]),('ads','Ad accounts and Pages',ADS[:4])],
     [BEFORE,SEND],
     DIRS+', '+L('meta-appeal-links-uae','Meta appeal links UAE')+', '+L(f'white-label-agency-{slug.split("links-")[1]}',f'white-label agency {country}')+'.',
     [('Can I call Meta in '+country+'?','Meta does not offer a phone line for account appeals. Use the in-product routes on this page.'),('Is my appeal handled differently in '+country+'?','The routes are the same worldwide. The notice and the language may differ.'),('I emailed my appeal letter to Meta. Did it arrive?','Meta does not process account appeals by email. Paste a short version into the appeal field in the app.')])
def ind(slug,who,plat,title,answer,risks,faqs):
    return mk(slug,title,f'{who}: account restricted',f'{plat} restricted or disabled for {who.lower()}: what usually triggers it, where to appeal, and what to send. Updated November 2026.',
     f'{plat} account down? A guide for {who.lower()}.','Your bookings, leads and messages run through this account. Here is where to start.',answer,
     [('Notice','Screenshot it first.'),('Admins','Check who still has access.'),('Appeal','Once, in plain words.')],
     '<h2 id="common-triggers">What commonly triggers it in your industry</h2><ul>'+''.join(f'<li>{r}</li>' for r in risks)+'</ul>',
     [('ig','Instagram',IG[:3]),('fb','Facebook and Pages',FB[:3]),('ads','Ads and Business Portfolio',[AQ,BV,ADS[1]])],
     [BEFORE,SEND],DIRS+', '+L('for-agencies-banned-client-accounts','agency hub')+', '+L('local-business-facebook-page-disabled','local business Page disabled') if False else DIRS+', '+L('for-agencies-banned-client-accounts','agency hub')+'.',faqs)
def ag(slug,country,wl):
    return mk(slug,f'Agency Client Account Banned in {country}: Instagram, Facebook, Ads (2026)',f'Agencies {country}',
     f'For agencies in {country} whose client Instagram, Facebook Page, ad account or Business Portfolio got banned. Who appeals, what to collect, how white-label referral works.',
     f'Agency in {country}? A client account got banned.','Clients look to you first. Here is how to sort out who acts, and what to collect today.',
     f'<strong>When a client account is banned, the person who owns it, or an admin, has to appeal from their own login.</strong> As an agency in {country}, collect the notice screenshot, check which asset is restricted in Business Support Home, and keep your own admin profile clean. You can refer the client to us under your brand. Meta makes the final decision.',
     [('Which asset','Profile, Page, ad account or Portfolio.'),('Who appeals','The owner or an admin.'),('White-label','We work behind your brand.')],
     f'<h2 id="agency-steps">Steps for {country} agencies</h2><ol><li>Ask the client for a screenshot of the notice and the date.</li><li>In Business Support Home, check whether the restriction is on the client’s profile, their Page, the ad account or the Portfolio.</li><li>Do not request reviews from several admin profiles at once.</li><li>If your own profile got restricted while managing the client, appeal that first.</li><li>Agree with the client who writes the appeal.</li></ol><p>See '+L(wl,f'white-label agency {country}')+'.</p>',
     [('ads','Business tools',[AQ,BV,ADS[0],ADS[1]]),('ig','Client Instagram',IG[:3])],[BEFORE,SEND],
     L('for-agencies-banned-client-accounts','agency hub')+', '+L('questions-agencies-ask-about-banned-client-accounts','questions agencies ask')+', '+L(wl,'white-label '+country)+'.',
     [('Can our agency appeal on behalf of the client?','Only through an admin login on the affected asset. Meta has no separate agency appeal form.'),('Will the client know we referred them?','In a white-label setup we speak through you, under your brand.'),('Our ad account was banned with the client’s. What first?','Check whether your own personal profile is restricted. That usually needs to be resolved before assets you manage.')])
